import {esc,allRows,allTable,changeGuard} from './organiser-utils.js';
import {editorStyles} from './visual-editor.js';
export const stages={new:'New',shortlisted:'Shortlisted',interview:'Interview',selected:'Selected',not_selected:'Not selected'};
export const isApplication=r=>r.details?.intent==='2027 organising committee application'||String(r.details?.application_version)==='2';
export async function openRecruitment({api,sb,host,editor,status,isCurrent}){
 editorStyles();editor.replaceChildren();
 const [all,reviews]=await Promise.all([allRows(api,'elan_enquiries'),allTable(sb,'elan_oc_recruitment')]);if(!isCurrent())return;
 const rows=all.filter(isApplication),saved=new Map(reviews.map(r=>[r.enquiry_id,r]));let dirty=false,busy=false,sequence=0;
 changeGuard(()=>dirty,()=>busy);
 const departments=[...new Set(rows.map(r=>r.details?.department).filter(Boolean))].sort();
 host.innerHTML=`<section class="app-card recruitment"><p class="app-badge">ÉLAN 2027 / RECRUITMENT</p><h2>Find your organising team.</h2><p>Read applications, record decisions and plan interviews here. Selecting someone does not grant access or send a message.</p><div class="recruitment-stages">${Object.entries(stages).map(([k,v])=>`<button data-stage="${k}" class="secondary"><strong data-total="${k}">0</strong>${v}</button>`).join('')}</div><div class="overview-filters"><label>Search applicants<input data-search type="search" placeholder="Name, email or skills"></label><label>Department<select data-department><option value="">All departments</option>${departments.map(d=>`<option>${esc(d)}</option>`).join('')}</select></label><label>Stage<select data-stage-filter><option value="">All stages</option>${Object.entries(stages).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label></div><p data-count role="status"></p><div class="recruitment-results"></div></section>`;
 const q=s=>host.querySelector(s),canLeave=()=>!busy&&(!dirty||confirm('Discard unsaved application review?'));
 function draw(){const term=q('[data-search]').value.toLowerCase(),dept=q('[data-department]').value,stage=q('[data-stage-filter]').value;
 const matches=rows.filter(r=>(!dept||r.details.department===dept)&&(!stage||(saved.get(r.id)?.stage||'new')===stage)&&JSON.stringify([r.full_name,r.email,r.details]).toLowerCase().includes(term)).sort((a,b)=>b.created_at.localeCompare(a.created_at));
 for(const k of Object.keys(stages))q(`[data-total="${k}"]`).textContent=rows.filter(r=>(saved.get(r.id)?.stage||'new')===k).length;
 q('[data-count]').textContent=matches.length+' applications';q('.recruitment-results').innerHTML=matches.map(r=>{const w=saved.get(r.id)||{};return `<article class="recruitment-card"><span class="app-badge">${stages[w.stage||'new']}</span><h3>${esc(r.full_name)}</h3><p>${esc(r.details.department||'Department not specified')} · ${esc(r.details.responsibility_level||'Applicant')}</p><p>${esc(r.details.institution||'')} ${esc(r.details.study_year||'')}</p><small>Applied ${new Date(r.created_at).toLocaleDateString()}${w.interview_at?' · Interview '+new Date(w.interview_at).toLocaleString():''}</small><button data-open="${esc(r.id)}">Review application ↗</button></article>`;}).join('')||'<p>No applications match. New submissions will appear here after applicants successfully submit the form.</p>';
 for(const b of host.querySelectorAll('[data-open]'))b.onclick=()=>{if(canLeave())edit(rows.find(r=>r.id===b.dataset.open));};
 }
 function edit(row){dirty=false;const token=++sequence;let w=saved.get(row.id)||{version:0,stage:'new'};
 const names={department:'First-choice department',second_department:'Second-choice department',responsibility_level:'Preferred responsibility',study_year:'Grade / year of study',work_sample:'Work sample link',department_question:'Practical question',department_answer:'Practical response',leadership_answer:'Leadership response',weekly_hours:'Weekly availability',missed_deadline:'Handling a missed deadline'};
 editor.innerHTML=`<section class="app-card recruitment-detail"><p class="app-badge">APPLICATION / 2027</p><h2>${esc(row.full_name)}</h2><a href="mailto:${esc(row.email)}">${esc(row.email)}</a><p>Submitted ${new Date(row.created_at).toLocaleString()}</p><details open><summary>Full application</summary><dl>${Object.entries(row.details||{}).filter(([k])=>!['intent','application_version','elan_hp','contact_consent'].includes(k)).map(([k,v])=>`<dt>${esc(names[k]||k.replaceAll('_',' '))}</dt><dd>${esc(v||'Not provided')}</dd>`).join('')}</dl></details><form><h3>Your review</h3><label>Recruitment stage<select name="stage">${Object.entries(stages).map(([k,v])=>`<option value="${k}" ${k===w.stage?'selected':''}>${v}</option>`).join('')}</select></label><label>Private reviewer notes<textarea name="notes" maxlength="6000" rows="5">${esc(w.notes||'')}</textarea></label><label>Interview date and time (your local time)<input type="datetime-local" name="interview"></label><label>Interview arrangements<textarea name="arrangements" maxlength="1000" placeholder="Meeting link, interviewer or location">${esc(w.interview_details||'')}</textarea></label><p>These details are private. Contact the applicant separately to confirm an interview or decision.</p><button>Save review</button><p role="status"></p></form><details><summary>Review history</summary><div data-history>Loading history…</div></details><a href="/admin.html?section=oc_control">Manage organiser access separately ↗</a></section>`;
 const f=editor.querySelector('form'),msg=f.querySelector('[role=status]');
 if(w.interview_at){const d=new Date(w.interview_at);f.elements.interview.value=new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
 f.oninput=()=>dirty=true;
 async function history(){const r=await sb.from('elan_oc_recruitment_history').select('stage,notes,interview_at,interview_details,created_at').eq('enquiry_id',row.id).order('created_at',{ascending:false}).limit(30);if(token!==sequence||!isCurrent())return;editor.querySelector('[data-history]').innerHTML=r.error?esc(r.error.message):r.data.map(h=>`<p><strong>${stages[h.stage]}</strong> · ${new Date(h.created_at).toLocaleString()}<br>${esc(h.notes)}${h.interview_at?'<br>Interview: '+esc(new Date(h.interview_at).toLocaleString()):''}<br>${esc(h.interview_details)}</p>`).join('')||'<p>No reviews saved yet.</p>';}
 history();f.onsubmit=async e=>{e.preventDefault();if(busy||!f.reportValidity())return;busy=true;f.inert=true;try{const r=await sb.rpc('elan_save_recruitment',{p_id:row.id,p_stage:f.elements.stage.value,p_notes:f.elements.notes.value.trim(),p_interview:f.elements.interview.value?new Date(f.elements.interview.value).toISOString():null,p_details:f.elements.arrangements.value.trim(),p_expected:w.version});if(r.error)throw r.error;w=Array.isArray(r.data)?r.data[0]:r.data;saved.set(row.id,w);dirty=false;msg.textContent='Review saved. No message was sent and access has not changed.';draw();await history();}catch(err){msg.textContent=err.message;}finally{busy=false;f.inert=false;}};editor.scrollIntoView({block:'start'});
 }
 for(const field of host.querySelectorAll('.overview-filters input,.overview-filters select')){field.dataset.previous=field.value;field.onchange=()=>{if(!canLeave()){field.value=field.dataset.previous;return;}field.dataset.previous=field.value;dirty=false;sequence++;editor.replaceChildren();draw();};}
 for(const b of host.querySelectorAll('[data-stage]'))b.onclick=()=>{if(!canLeave())return;dirty=false;sequence++;editor.replaceChildren();q('[data-stage-filter]').value=b.dataset.stage;q('[data-stage-filter]').dataset.previous=b.dataset.stage;draw();};draw();status('');
}
